<script setup>
import { createRecoveryStorage } from '@/lib/recovery-storage'
import MallMemberRules from '@/components/MallMemberRules.vue'
import MallBatchShipping from './MallBatchShipping.vue'
import { computed, onMounted, onBeforeUnmount, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import request from '@/lib/request'
import { useUserStore } from '@/stores/user'
import { newRequestKey } from '@/lib/operations'
import { mallMoney, mallDate, mallProvinces } from '@/lib/mall'
import { phase2Text, parseBatchCsv, downloadCsv, canReleaseMallIntent, memberTiersForForm, memberTiersForSave } from '@/lib/mall2'

const route = useRoute(), user = useUserStore(), tab = route.meta.mallGrowth
const recoveryStorage = createRecoveryStorage(localStorage, user.userInfo?.id)
const app = user.product('MALL')?.application?.id, root = `/mall/apps/${app}/v2`
const title = { members: '商城会员', 'member-rules': '会员规则与等级', coupons: '商城优惠券', shipping: '配送与物流', batch: '批量工作台', sharing: '点餐与商城共享' }[tab]
const batchRevision = ref(0), memberRulesDirty = ref(false)
const batchMode = route.query.mode || 'all'
const basicDelivery = reactive({})
const config = reactive({}), shipping = reactive({}), sharing = reactive({})
const list = ref([]), coupons = ref([]), candidates = ref([]), bindings = ref([]), mallSkus = ref([]), integrations = ref([])
const page = ref(1), total = ref(0), birthdays = ref(false), loading = ref(false), loaded = ref(false), busy = ref(false), error = ref(''), recoveryError = ref(''), result = ref(null), pending = ref(null)
const editor = ref(''), form = reactive({}), csv = ref(''), preview = ref(null), batchCsv = ref(''), exportForm = reactive({ startsOn: route.query.startsOn || '', endsOn: route.query.endsOn || '', reason: '' }), ledger = ref(null), ledgerOpen = ref(false)
const canEdit = computed(() => user.hasPermission('settings:edit')), blocked = computed(() => busy.value || !!pending.value)
const canEditMembers = computed(() => user.hasPermission('operations:edit', 'MALL'))
const canManageCoupons = computed(() => user.hasPermission('coupon:manage', 'MALL'))
const sharedAction = legacy => user.hasPermission(legacy === 'product:view' ? 'sharing:copy' : legacy === 'warehouse:view' ? 'sharing:bind' : 'sharing:manage', 'MALL')
function actionPermission(path) {
  if (/^\/sharing\//.test(path)) return sharedAction(path === '/sharing/copy-product' ? 'product:view' : 'warehouse:view')
  if (/^\/coupons/.test(path) || path === '/birthday-run') return canManageCoupons.value
  if (/\/mock-topup$/.test(path)) return user.hasPermission('wallet:topup', 'MALL')
  if (path === '/import-confirm') return user.hasPermission('product:create', 'MALL')
  if (path === '/batch-ship') return user.hasPermission('order:ship', 'MALL')
  if (path === '/order-export') return user.hasPermission('finance:export', 'MALL')
  if (/^\/integrations\//.test(path)) return canEdit.value
  return false
}
function editorAllowed(type) { return type === 'coupon' ? canManageCoupons.value : type === 'topup' ? user.hasPermission('wallet:topup', 'MALL') : type === 'bind' ? sharedAction('warehouse:view') : type === 'integration' ? canEdit.value : false }
const storageKey = `mall-growth:${user.currentStoreId}:${app}:${user.userInfo?.id}`
let disposed = false, loadGeneration = 0
let ledgerGeneration = 0
try { const raw = recoveryStorage.getItem(storageKey); if (raw) pending.value = JSON.parse(raw) } catch (e) { recoveryError.value = e.code === 'RECOVERY_LEGACY' ? e.message : '原操作恢复记录无法读取，请联系店长核对；原记录已保留。'; pending.value = { damaged: true } }
function replace(target, value) { Object.keys(target).forEach(key => delete target[key]); Object.assign(target, value) }
async function load() {
  const generation = ++loadGeneration
  const current = () => !disposed && generation === loadGeneration
  loading.value = true; error.value = ''; loaded.value = false
  try {
    if (['members', 'member-rules', 'coupons'].includes(tab)) { const [c, m, t] = await Promise.all([request.get(`${root}/members/config`), tab === 'members' ? request.get(`${root}/members`, { params: { page: page.value, size: 20, birthdays: birthdays.value } }) : Promise.resolve({ list: [], total: 0 }), tab === 'coupons' ? request.get(`${root}/coupons`) : Promise.resolve({ list: [] })]); if (!current()) return; replace(config, { ...c, tiers: memberTiersForForm(c.tiers) }); list.value = m.list; total.value = m.total; coupons.value = t.list }
    else if (tab === 'shipping') { const [s, i, basic] = await Promise.all([request.get(`${root}/shipping`), user.hasPermission('settings:view', 'MALL') ? request.get(`${root}/integrations`) : Promise.resolve({ list: [] }), request.get(`/mall/apps/${app}/settings`)]); if (!current()) return; replace(basicDelivery, basic); replace(shipping, { ...s, localAreasText: s.localAreas.join('\n') }); integrations.value = i.list.filter(item => ['TRACKING', 'WAYBILL', 'LOCAL_DELIVERY'].includes(item.kind)) }
    else if (tab === 'sharing') { const s = await request.get(`${root}/sharing`); if (!current()) return; replace(sharing, s); if (user.hasPermission('warehouse:view')) { const b = await request.get(`${root}/sharing/inventory`); if (current()) bindings.value = b.list } if (sharedAction('product:view') || sharedAction('warehouse:view')) { const c = await request.get(`${root}/sharing/candidates`); if (!current()) return; candidates.value = c.list } if (sharedAction('warehouse:view')) { const p = await request.get(`${root}/sharing/mall-candidates`); if (!current()) return; mallSkus.value = p.list.map(sku => ({ ...sku, label: `${sku.name} · ${sku.skuCode}` })) } }
    if (current()) loaded.value = true
  } catch (e) { if (current()) error.value = e.message || '加载失败，请重试' }
  finally { if (current()) loading.value = false }
}
async function saveBasicDelivery() {
  if (blocked.value || !loaded.value || !canEdit.value) return
  busy.value = true; error.value = ''
  try { await request.put(`/mall/apps/${app}/settings`, { ...basicDelivery, expectedVersion: basicDelivery.version }); ElMessage.success('基础配送已保存'); await load() }
  catch (e) { error.value = `${e.message}。请刷新后核对设置`; loaded.value = false }
  finally { busy.value = false }
}
async function save(type, draft = null) {
  const allowed = type === 'members' ? canEditMembers.value : type === 'sharing' ? sharedAction('settings:edit') : canEdit.value
  if (blocked.value || !loaded.value || !allowed) return
  busy.value = true; error.value = ''
  try { const value = type === 'members' ? { ...(draft || config), tiers: memberTiersForSave((draft || config).tiers) } : type === 'shipping' ? { ...shipping, localAreas: shipping.localAreasText.split('\n').map(s => s.trim()).filter(Boolean) } : sharing; await request.put(`${root}/${type === 'members' ? 'members/config' : type}`, { ...value, expectedVersion: value.version }); ElMessage.success('设置已保存'); await load() }
  catch (e) { error.value = `${e.message}。请刷新读取最新设置再调整`; if (type !== 'members') loaded.value = false }
  finally { busy.value = false }
}
function open(type, row = {}) {
  if (blocked.value || !editorAllowed(type)) return
  replace(form, type === 'coupon' ? { name: '', kind: 'GENERAL', amount: 5, minimum: 20, startsOn: '', endsOn: '', totalLimit: 1000, perCustomer: 1, active: true, ...row } : type === 'topup' ? { customer: row.customerId, amount: 10, reason: '', confirmedMock: false } : type === 'integration' ? { ...row, accountId: '', secret: '', endpoint: '', reference: '人工模拟验收' } : { mallSkuId: null, diningSkuId: null, confirmDiningAuthority: false }); editor.value = type
}
async function submit() {
  if (blocked.value || !editorAllowed(editor.value)) return
  try {
    if (editor.value === 'coupon') return send('/coupons' + (form.id ? `/${form.id}` : ''), { ...form, expectedVersion: form.version }, form.id ? 'put' : 'post')
    if (editor.value === 'topup') return send(`/members/${form.customer}/mock-topup`, { amount: form.amount, reason: form.reason, confirmedMock: form.confirmedMock })
    if (editor.value === 'bind') { const sku = candidates.value.find(s => s.id === form.diningSkuId); if (!sku) throw new Error('请选择点餐规格'); return send('/sharing/inventory', { ...form, expectedPhysicalStock: sku.stockQuantity }) }
    if (editor.value === 'integration') { busy.value = true; const credentials = Object.fromEntries(['accountId', 'secret', 'endpoint'].filter(key => String(form[key] || '').trim()).map(key => [key, String(form[key]).trim()])); await request.put(`${root}/integrations/${form.kind}`, { expectedVersion: form.version, mode: form.mode, provider: form.provider, credentials }); editor.value = ''; await load() }
  } catch (e) { error.value = e.message }
  finally { busy.value = false }
}
async function send(path, body = {}, method = 'post') {
  if (blocked.value || !actionPermission(path)) return
  const operation = { path, body: { ...body, requestKey: newRequestKey() }, method }
  try { recoveryStorage.setItem(storageKey, JSON.stringify(operation)); pending.value = operation } catch { error.value = '无法保存操作恢复记录，暂不能提交'; return }
  return recover()
}
async function recover() {
  const operation = pending.value
  if (busy.value || !operation || operation.damaged) return
  if (!actionPermission(operation.path)) { error.value = '当前账号无权重试原操作，请联系店长核对'; return }
  if (!/^\/(coupons(?:\/\d+)?|members\/\d+\/mock-topup|sharing\/(?:inventory(?:\/\d+\/unbind)?|copy-product)|birthday-run|import-confirm|batch-ship|order-export|integrations\/(?:TRACKING|WAYBILL|LOCAL_DELIVERY)\/simulate)$/.test(operation.path) || !['post', 'put'].includes(operation.method) || !operation.body?.requestKey) { error.value = '原操作格式无法确认，请联系店长核对'; return }
  busy.value = true; error.value = ''
  try { const value = await request[operation.method](`${root}${operation.path}`, operation.body, { timeout: 60000, silent: true }); if (disposed) return; result.value = value; if (value.list?.some(row => row.status === 'UNKNOWN')) { error.value = '部分结果未确认，请保留原批次并点击原请求重试'; return } if (operation.path === '/batch-ship') batchRevision.value++; recoveryStorage.removeItem(storageKey); pending.value = null; editor.value = ''; if (value.csv) downloadCsv(value.fileName, value.csv); ElMessage.success('操作结果已返回'); await load() }
  catch (e) { if (!disposed) { error.value = e.message || '结果待确认，请保留原请求重试'; if (canReleaseMallIntent(e)) { recoveryStorage.removeItem(storageKey); pending.value = null } } }
  finally { if (!disposed) busy.value = false }
}
async function importPreview() { if (blocked.value || !user.hasPermission('product:create', 'MALL')) return; busy.value = true; preview.value = null; error.value = ''; try { preview.value = await request.post(`${root}/import-preview`, { csv: csv.value }) } catch (e) { error.value = e.message } finally { busy.value = false } }
async function readFile(event) { const file = event.target.files?.[0]; if (!file) return; if (file.size > 1000000) { error.value = '文件不能超过1MB'; return } csv.value = await file.text(); preview.value = null }
async function inspectLedger(row) {
  if (!user.hasPermission('finance:view', 'MALL')) return
  const generation = ++ledgerGeneration
  const current = () => !disposed && ledgerOpen.value && generation === ledgerGeneration
  ledgerOpen.value = true; ledger.value = null; error.value = ''
  try { const value = await request.get(`${root}/members/${row.customerId}/ledger`); if (current()) ledger.value = value }
  catch (e) { if (current()) { error.value = e.message; ledgerOpen.value = false } }
}
function closeLedger() { ledgerGeneration++; ledgerOpen.value = false; ledger.value = null }
function bulkShip() { try { const rows = parseBatchCsv(batchCsv.value, ['orderId', 'expectedVersion', 'carrier', 'trackingNo']); for (const row of rows) { if (!/^\d+$/.test(row.orderId) || !/^\d+$/.test(row.expectedVersion)) throw new Error('订单编号和资料版本必须为整数'); row.orderId = Number(row.orderId); row.expectedVersion = Number(row.expectedVersion) } send('/batch-ship', { rows }) } catch (e) { error.value = e.message } }
async function unbind(row) { try { await ElMessageBox.confirm('解除后商城规格库存清零，点餐实物库存保留；商城需独立盘点入库后再售卖。存在可售后订单时系统会阻止解除。', '确认解除库存关联'); await send(`/sharing/inventory/${row.id}/unbind`, { expectedVersion: row.version }) } catch (e) { if (e instanceof Error) error.value = e.message } }
async function refreshPage() {
  if (memberRulesDirty.value && tab === 'member-rules') { try { await ElMessageBox.confirm('刷新会放弃尚未保存的会员规则修改。', '重新读取规则？', { confirmButtonText: '放弃并刷新', cancelButtonText: '继续编辑', type: 'warning' }) } catch { return } }
  await load()
}
onMounted(load); onBeforeUnmount(() => { disposed = true; loadGeneration++; closeLedger() })
</script>

<template>
  <section class="growth-page" v-loading="loading">
    <header><div><p class="eyebrow">商城经营</p><h1>{{ title }}</h1><p class="muted">按门店管理，历史订单保留原规则。</p></div><el-button @click="refreshPage" :disabled="busy">刷新</el-button></header>
    <el-alert v-if="recoveryError || error" :title="recoveryError || error" type="error" :closable="false" />
    <el-alert v-if="pending" title="有一项操作的结果待确认，请使用原请求继续核对。" type="warning" :closable="false"><el-button :loading="busy" :disabled="pending.damaged || !actionPermission(pending.path)" @click="recover">原请求重试</el-button></el-alert>
    <nav v-if="['members', 'coupons'].includes(tab)" class="mall-subnav"><RouterLink to="/mall/members">会员名单</RouterLink><RouterLink to="/mall/member-rules">会员规则与等级</RouterLink><RouterLink to="/mall/coupons">优惠券活动</RouterLink></nav>
    <template v-if="['members', 'member-rules', 'coupons'].includes(tab) && loaded">
      <MallMemberRules v-if="tab === 'member-rules'" :config="config" :busy="blocked" :readonly="!canEditMembers" @dirty="memberRulesDirty = $event" @save="save('members', $event)" />
      <section v-if="tab === 'coupons'" class="panel"><header><h2>优惠券</h2><div class="actions"><el-button v-if="canManageCoupons" :disabled="blocked || !user.canTradeProduct('MALL')" @click="send('/birthday-run')">执行生日活动</el-button><el-button v-if="canManageCoupons" type="primary" :disabled="blocked || !user.canTradeProduct('MALL')" @click="open('coupon')">新建券</el-button></div></header><div class="scroll-table"><el-table :data="coupons"><el-table-column prop="name" label="券名称" min-width="140" /><el-table-column label="类型"><template #default="{ row }">{{ phase2Text(row.kind) }}</template></el-table-column><el-table-column label="优惠"><template #default="{ row }">满{{ row.minimum }}减{{ row.amount }}</template></el-table-column><el-table-column label="已发 / 总量"><template #default="{ row }">{{ row.issued }}/{{ row.totalLimit }}</template></el-table-column><el-table-column label="有效期" min-width="190"><template #default="{ row }">{{ row.startsOn }} 至 {{ row.endsOn }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }">{{ row.active ? '启用' : '停用' }}</template></el-table-column><el-table-column label="操作"><template #default="{ row }"><el-button v-if="canManageCoupons" link :disabled="blocked" @click="open('coupon', row)">编辑</el-button></template></el-table-column></el-table></div></section>
      <section v-if="tab === 'members'" class="panel"><header><h2>商城会员</h2><el-checkbox v-model="birthdays" @change="page = 1; load()">未来30天生日</el-checkbox></header><div class="scroll-table"><el-table :data="list"><el-table-column prop="customerId" label="会员编号" /><el-table-column prop="nickname" label="昵称" /><el-table-column prop="birthday" label="生日" min-width="120" /><el-table-column label="等级"><template #default="{ row }">{{ row.tier?.name }}</template></el-table-column><el-table-column prop="points" label="积分" /><el-table-column prop="growth" label="成长值" /><el-table-column prop="balance" label="商城余额" /><el-table-column label="操作" min-width="150"><template #default="{ row }"><el-button v-if="user.hasPermission('finance:view')" link @click="inspectLedger(row)">流水</el-button><el-button v-if="user.hasPermission('wallet:topup', 'MALL') && config.walletEnabled && config.walletMode === 'MOCK'" :disabled="blocked" link @click="open('topup', row)">模拟充值</el-button></template></el-table-column></el-table></div><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev, pager, next" :pager-count="5" @current-change="load" /></section>
    </template>
    <template v-if="tab === 'shipping' && loaded"><section class="panel"><h2>基础配送方式</h2><p class="muted">固定运费用于未启用高级运费模板时；当前订单的运费快照不受设置修改影响。</p><el-form label-position="top" @submit.prevent="saveBasicDelivery"><fieldset :disabled="blocked || !canEdit"><div class="grid"><el-form-item label="快递配送"><el-switch v-model="basicDelivery.expressEnabled" /></el-form-item><el-form-item label="到店自提"><el-switch v-model="basicDelivery.pickupEnabled" /></el-form-item><el-form-item label="固定运费（元）"><el-input-number v-model="basicDelivery.shippingFee" :min="0" :precision="2" /></el-form-item><el-form-item label="满额包邮（元，留空不启用）"><el-input-number v-model="basicDelivery.freeShippingThreshold" :min="0" :precision="2" /></el-form-item><el-form-item label="自提地址"><el-input v-model="basicDelivery.pickupAddress" maxlength="255" /></el-form-item></div><el-form-item label="暂停配送的省份"><el-select v-model="basicDelivery.blockedProvinces" multiple><el-option v-for="province in mallProvinces" :key="province" :label="province" :value="province" /></el-select></el-form-item><el-button native-type="submit" type="primary">保存基础配送</el-button></fieldset></el-form></section><section class="panel"><h2>高级运费模板</h2><el-form label-position="top" @submit.prevent="save('shipping')"><fieldset :disabled="blocked || !canEdit"><div class="grid"><el-form-item label="启用模板（关闭时沿用商城固定运费）"><el-switch v-model="shipping.enabled" /></el-form-item><el-form-item label="计费依据"><el-select v-model="shipping.basis"><el-option value="QUANTITY" label="商品件数" /><el-option value="WEIGHT_GRAMS" label="商品总重量（克）" /></el-select></el-form-item><el-form-item label="优惠前商品金额满额包邮（留空关闭）"><el-input-number v-model="shipping.freeThreshold" :min="0.01" :precision="2" :value-on-clear="null" /></el-form-item></div><article v-for="(rule, index) in shipping.rules" :key="index" class="rule"><el-form-item label="适用省份（留空为默认规则）"><el-select v-model="rule.provinces" multiple filterable><el-option v-for="p in mallProvinces" :key="p" :value="p" :label="p" /></el-select></el-form-item><div class="grid"><el-form-item label="首件 / 首重（克）"><el-input-number v-model="rule.firstUnits" :min="1" :precision="0" /></el-form-item><el-form-item label="首费（元）"><el-input-number v-model="rule.firstFee" :min="0" :precision="2" /></el-form-item><el-form-item label="每续件 / 续重（克）"><el-input-number v-model="rule.extraUnits" :min="1" :precision="0" /></el-form-item><el-form-item label="续费（元）"><el-input-number v-model="rule.extraFee" :min="0" :precision="2" /></el-form-item></div><el-button link type="danger" @click="shipping.rules.splice(index, 1)">移除此规则</el-button></article><el-button @click="shipping.rules.push({ provinces: [], firstUnits: 1, firstFee: 5, extraUnits: 1, extraFee: 1 })">添加运费规则</el-button><h2>同城配送模拟</h2><div class="grid"><el-form-item label="启用同城配送"><el-switch v-model="shipping.localEnabled" /></el-form-item><el-form-item label="运行状态"><el-select v-model="shipping.localMode"><el-option label="未启用" value="DISABLED" /><el-option label="模拟配送" value="MOCK" /></el-select></el-form-item><el-form-item label="同城费用（元）"><el-input-number v-model="shipping.localFee" :min="0" :precision="2" /></el-form-item></div><el-form-item label="配送区域，每行填写 城市/区县（与收货地址保持一致）"><el-input v-model="shipping.localAreasText" type="textarea" :rows="4" placeholder="长沙市/雨花区" /></el-form-item><p class="muted">同城订单和模拟面单不会呼叫真实骑手或承运商。</p><el-button type="primary" native-type="submit">保存配送设置</el-button></fieldset></el-form></section><section class="panel"><h2>物流服务配置</h2><article v-for="item in integrations" :key="item.kind" class="integration"><div><strong>{{ { TRACKING: '物流轨迹', WAYBILL: '电子面单', LOCAL_DELIVERY: '同城配送' }[item.kind] }}</strong><p class="muted">{{ phase2Text(item.mode) }} · 真实调用未启用</p></div><div class="actions"><el-button v-if="canEdit" :disabled="blocked" @click="open('integration', item)">配置</el-button><el-button v-if="canEdit && item.mode === 'MOCK'" :disabled="blocked" @click="send(`/integrations/${item.kind}/simulate`, { reference: '人工模拟验收' })">模拟验收</el-button></div></article></section></template>
    <template v-if="tab === 'batch'"><MallBatchShipping v-if="user.hasPermission('order:ship', 'MALL') && ['all', 'ship'].includes(batchMode)" :key="batchRevision" :app="app" :disabled="blocked" @submit="send('/batch-ship', { rows: $event })" /><section v-if="user.hasPermission('product:create', 'MALL') && ['all', 'import'].includes(batchMode)" class="panel"><h2>批量新增商品</h2><p class="muted">最多200行，只新增未上架商品。先预检，全部通过后再导入。</p><div class="actions"><el-button @click="downloadCsv('products-template.csv', 'name,skuCode,price,stock,weightGrams,specs\r\n示例商品,DEMO-SKU,10,20,500,\r\n')">下载模板</el-button><label class="file">读取CSV文件<input type="file" accept=".csv,text/csv" :disabled="blocked" @change="readFile"></label></div><el-input v-model="csv" type="textarea" :rows="6" placeholder="粘贴CSV内容" :disabled="blocked" @input="preview = null" /><div class="actions"><el-button :disabled="blocked || !csv" @click="importPreview">预检</el-button><el-button type="primary" :disabled="blocked || !preview?.valid" @click="send('/import-confirm', { csv, previewHash: preview.previewHash })">确认导入 {{ preview?.total || 0 }} 行</el-button></div><template v-if="preview"><p>{{ preview.valid ? '预检通过' : '请修正错误后重新预检' }} · {{ preview.total }}行</p><p v-for="item in preview.errors" :key="item.row" class="failure">第{{ item.row }}行：{{ item.message }}</p></template></section><details v-if="user.hasPermission('order:ship', 'MALL') && ['all', 'ship'].includes(batchMode)" class="panel"><summary>通过CSV登记运单（可选）</summary><section><h2>批量登记运单</h2><p class="muted">每批最多50单，一单一行；每单分别提交并报告结果。需拆包裹的订单请到订单详情处理。</p><el-input v-model="batchCsv" type="textarea" :rows="5" :disabled="blocked" placeholder="orderId,expectedVersion,carrier,trackingNo" /><el-button :disabled="blocked || !batchCsv" @click="bulkShip">提交批次</el-button></section></details><section v-if="user.hasPermission('finance:export', 'MALL') && ['all', 'export'].includes(batchMode)" class="panel"><h2>导出商城订单</h2><p class="muted">最多31天、5000笔；超过上限会拒绝导出。文件不含姓名、手机号和地址，每次导出保留操作记录。</p><el-form label-position="top" @submit.prevent="send('/order-export', exportForm)"><div class="grid"><el-form-item label="开始日期"><el-date-picker v-model="exportForm.startsOn" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="exportForm.endsOn" value-format="YYYY-MM-DD" /></el-form-item></div><el-form-item label="导出用途"><el-input v-model="exportForm.reason" maxlength="255" /></el-form-item><el-button native-type="submit" :disabled="blocked">生成并下载</el-button></el-form></section></template>
    <template v-if="tab === 'sharing' && loaded"><section class="panel"><h2>共享范围</h2><el-form @submit.prevent="save('sharing')"><fieldset :disabled="blocked || !sharedAction('settings:edit')"><div class="switches"><el-checkbox v-model="sharing.products">允许复用点餐商品资料</el-checkbox><el-checkbox v-model="sharing.inventory">允许关联实物库存</el-checkbox><el-checkbox v-model="sharing.members">允许顾客确认关联会员身份</el-checkbox></div><p class="muted">复制商品后可独立编辑价格和详情。库存需逐个规格关联，以点餐库存为唯一实物数量；两侧钱包、积分、优惠券各自管理。</p><el-button type="primary" native-type="submit">保存共享范围</el-button></fieldset></el-form></section><section v-if="sharedAction('product:view')" class="panel"><h2>复用商品</h2><el-select v-model="form.copyProductId" filterable placeholder="选择点餐商品" :disabled="blocked || !sharing.products"><el-option v-for="p in [...new Map(candidates.map(s => [s.productId, s])).values()]" :key="p.productId" :label="p.name" :value="p.productId" /></el-select><el-button :disabled="blocked || !form.copyProductId || !sharing.products" @click="send('/sharing/copy-product', { productId: form.copyProductId })">复制为商城草稿</el-button><p class="muted">只复制资料，不复制库存。最多展示最近500个点餐规格和500个商城规格。</p></section><section v-if="user.hasPermission('warehouse:view')" class="panel"><header><h2>库存关联</h2><el-button :disabled="blocked || !sharing.inventory || !sharedAction('warehouse:view')" @click="open('bind')">新增关联</el-button></header><div class="scroll-table"><el-table :data="bindings"><el-table-column prop="mallSkuId" label="商城规格" /><el-table-column prop="diningSkuId" label="点餐规格" /><el-table-column prop="physicalStock" label="实物库存" /><el-table-column prop="reserved" label="商城预留" /><el-table-column label="状态"><template #default="{ row }">{{ row.active ? '已关联' : '已解除' }}</template></el-table-column><el-table-column label="操作"><template #default="{ row }"><el-button v-if="row.active && sharedAction('warehouse:view')" link :disabled="blocked" @click="unbind(row)">解除</el-button></template></el-table-column></el-table></div></section></template>
    <section v-if="result" class="panel" aria-live="polite"><h2>最近操作结果</h2><template v-if="result.list"><article v-for="(row, index) in result.list" :key="index" class="integration"><span>第{{ row.row }}行 · 订单 #{{ row.orderId }}</span><span>{{ phase2Text(row.status) }} {{ row.message || '' }}</span></article></template><template v-else><p v-if="result.mode === 'MOCK'">模拟完成，未调用真实外部服务。</p><p v-if="result.count != null">处理 {{ result.count }} 条记录</p><p v-if="result.trackingNo">模拟单号：{{ result.trackingNo }}</p><el-button v-if="result.csv" @click="downloadCsv(result.fileName, result.csv)">重新下载原文件</el-button></template></section>
    <el-dialog :model-value="!!editor" :title="{ coupon: form.id ? '编辑优惠券' : '新建优惠券', topup: '增加商城演示余额', bind: '关联库存', integration: '配置模拟接入' }[editor]" width="min(640px, 94vw)" :close-on-click-modal="!busy" :show-close="!busy" @close="editor = ''"><el-form label-position="top" @submit.prevent="submit"><fieldset :disabled="blocked || !editorAllowed(editor)"><template v-if="editor === 'coupon'"><el-form-item label="券名称"><el-input v-model="form.name" maxlength="80" :disabled="form.issued > 0" /></el-form-item><div class="grid"><el-form-item label="券类型"><el-select v-model="form.kind" :disabled="form.issued > 0"><el-option label="普通券（顾客领取）" value="GENERAL" /><el-option label="生日券（活动发放）" value="BIRTHDAY" /></el-select></el-form-item><el-form-item label="最低商品金额"><el-input-number v-model="form.minimum" :min="0" :precision="2" :disabled="form.issued > 0" /></el-form-item><el-form-item label="减免金额"><el-input-number v-model="form.amount" :min="0.01" :precision="2" :disabled="form.issued > 0" /></el-form-item><el-form-item label="总发放量"><el-input-number v-model="form.totalLimit" :min="form.issued ? form.totalLimit : 1" :max="1000000" :precision="0" /></el-form-item><el-form-item label="每人上限（生日券每年）"><el-input-number v-model="form.perCustomer" :min="1" :max="100" :precision="0" :disabled="form.issued > 0" /></el-form-item><el-form-item label="生效日期"><el-date-picker v-model="form.startsOn" value-format="YYYY-MM-DD" :disabled="form.issued > 0" /></el-form-item><el-form-item label="失效日期"><el-date-picker v-model="form.endsOn" value-format="YYYY-MM-DD" :disabled="form.issued > 0" /></el-form-item></div><el-checkbox v-model="form.active">启用发放和使用</el-checkbox><p class="muted">已发放的券仅支持停启和增加总量，修改规则需新建。</p></template><template v-else-if="editor === 'topup'"><el-alert title="仅增加演示余额，不代表实际收款。真实储值未启用。" type="warning" :closable="false" /><el-form-item label="模拟金额"><el-input-number v-model="form.amount" :min="0.01" :precision="2" /></el-form-item><el-form-item label="测试说明"><el-input v-model="form.reason" maxlength="255" /></el-form-item><el-checkbox v-model="form.confirmedMock">确认仅用于模拟测试</el-checkbox></template><template v-else-if="editor === 'bind'"><el-form-item label="商城规格"><el-select v-model="form.mallSkuId" filterable><el-option v-for="s in mallSkus" :key="s.id" :label="s.label" :value="s.id" /></el-select></el-form-item><el-form-item label="点餐规格（唯一实物库存）"><el-select v-model="form.diningSkuId" filterable><el-option v-for="s in candidates" :key="s.id" :label="`${s.name} · #${s.id} · 库存${s.stockQuantity}`" :value="s.id" /></el-select></el-form-item><el-checkbox v-model="form.confirmDiningAuthority">已盘点，确认使用点餐库存，不累加两侧数量</el-checkbox></template><template v-else-if="editor === 'integration'"><el-form-item label="提供方标识（预留配置）"><el-input v-model="form.provider" placeholder="大写英文，如 PENDING" maxlength="40" /></el-form-item><el-form-item label="运行方式"><el-select v-model="form.mode"><el-option label="未启用" value="DISABLED" /><el-option label="模拟模式" value="MOCK" /></el-select></el-form-item><el-form-item label="账号标识（选填，空白保留原值）"><el-input v-model="form.accountId" maxlength="1000" autocomplete="off" /></el-form-item><el-form-item label="密钥（选填，保存后不回显）"><el-input v-model="form.secret" type="password" maxlength="1000" autocomplete="new-password" /></el-form-item><el-form-item label="服务地址（选填）"><el-input v-model="form.endpoint" maxlength="1000" autocomplete="off" /></el-form-item><p class="muted">当前只保存配置和运行模拟，未启用真实服务。</p></template><div class="actions footer"><el-button @click="editor = ''">取消</el-button><el-button native-type="submit" type="primary">确认保存</el-button></div></fieldset></el-form></el-dialog>
    <el-drawer v-model="ledgerOpen" @close="closeLedger" title="商城会员流水" size="min(680px, 100%)"><p class="muted">{{ ledger?.mode === 'MOCK' ? '当前为模拟余额' : '真实充值未启用' }} · 点餐钱包另行管理</p><div v-if="ledger" class="scroll-table"><el-table :data="ledger.list"><el-table-column label="类型" min-width="150"><template #default="{ row }">{{ phase2Text(row.kind) }}</template></el-table-column><el-table-column label="金额"><template #default="{ row }">{{ mallMoney(row.amount) }}</template></el-table-column><el-table-column prop="points" label="积分变动" /><el-table-column label="时间" min-width="170"><template #default="{ row }">{{ mallDate(row.createdAt) }}</template></el-table-column></el-table></div><p v-if="ledger" class="muted">显示最近20条，共{{ ledger.total }}条。</p></el-drawer>
  </section>
</template>

